"""Evidence-only capture: assumes caller supplies read-only Git repository path."""
import sys,json,hashlib,subprocess,os,datetime
from pathlib import Path
D=Path(__file__).resolve().parent
repo=sys.argv[1]
def git(*a):return subprocess.check_output(['git','-C',repo,*a])
def load(n):return json.loads((D/n).read_text())
def save(n,o):(D/n).write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n')
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def sha(b):return hashlib.sha256(b).hexdigest()
new='95e63628f9d70b8dd6e6fede64334696c6995009';old='e2755a732c84e67296b5e3441a4259a84f461b2f'
rs=[]
for f in ['SOURCE-REGISTRATION.json','SUPPORT-REGISTRATION.json','SUPPORT2-REGISTRATION.json','SUPPORT3-REGISTRATION.json','SUPPORT4-REGISTRATION.json']:
 j=load(f)
 for r in j.get('sources',j.get('rows',[])):rs.append({'registration':f,'path':r['path'],'revision':new,'capture':r['capture'],'actual_ranges':r['planned_ranges'],'eof':r['eof'],'sha256':r['sha256']})
for f in ['SUPPORT5-REGISTRATION.json','SUPPORT6-REGISTRATION.json']:
 j=load(f)
 for r in j.get('rows',[j]):
  b=(D/r['capture']).read_bytes();rs.append({'registration':f,'path':r['path'],'revision':new,'capture':r['capture'],'actual_ranges':r['planned_ranges'],'eof':len(b.splitlines()),'sha256':r['sha256']})
for r in rs:
 covered=set(n for a,b in r['actual_ranges'] for n in range(a,b+1));unread=[];start=None
 for n in range(1,r['eof']+2):
  if n<=r['eof'] and n not in covered:
   if start is None:start=n
  elif start is not None:unread.append([start,n-1]);start=None
 r['unread_complement_for_this_registration']=unread
save('READ-RECEIPTS.json',{'reader':'/root/mhr_character','qualification':'Actual untruncated personal displays after prospectively registered ranges; full stored bytes do not imply whole-file personal reading. Complements are per registration, not global union. Test text was never run.','events':rs,'errors_and_limits':['One initial combined support display was tool-truncated. Every affected registered support window was then independently redisplayed untruncated; only the later complete displays support credit.','A subsequent fixed-string locator accidentally displayed a partial line at capture.rs:841 outside registered ranges; no registered-read or semantic credit is claimed for it.','One source locator was attempted in the wrong Git repository and returned 128 without source content; the registered search was re-run successfully in the evidence Git repository.','A generic directory listing was truncated and is not used for source or evidence conclusions.','The semantic.rs 1-80 support read included test-source text but proved no relevant DodgeSpec contract; tests were not run.']})
with (D/'DISPLAY-RECONSTRUCTED.txt').open('w') as w:
 w.write('Reconstructed text of the personally displayed registered source windows; this transcript is generated from captured exact source bytes and is not independent proof of human/model attention.\n')
 for r in rs:
  lines=(D/r['capture']).read_text().splitlines();w.write('\n=== '+r['registration']+' '+r['revision']+':'+r['path']+' ===\n')
  for a,b in r['actual_ranges']:
   w.write('--- %d-%d ---\n'%(a,b))
   for n in range(a,b+1):w.write('%5d %s\n'%(n,lines[n-1]))

# Raw trees prove path inclusions relative to recorded revision root hashes. No commit author data is copied.
(D/'git-trees').mkdir()
revpaths={}
for r in rs:revpaths.setdefault((new,r['path']),r['capture'])
for x in load('SOURCE-REGISTRATION.json')['sources']:revpaths[(old,x['path'])]=x['capture']
roots={rev:git('rev-parse',rev+'^{tree}').decode().strip() for rev in (old,new)}
proofs=[]
for (rev,path),cap in sorted(revpaths.items()):
 cur=roots[rev];chain=[]
 for i,part in enumerate(path.split('/')):
  raw=git('cat-file','tree',cur);fn=D/'git-trees'/f'{cur}.tree'
  if not fn.exists():fn.write_bytes(raw)
  found=None;offset=0
  while offset<len(raw):
   sp=raw.index(b' ',offset);zero=raw.index(b'\0',sp+1);mode=raw[offset:sp].decode();name=raw[sp+1:zero].decode();oid=raw[zero+1:zero+21].hex();offset=zero+21
   if name==part:found=(mode,oid);break
  if found is None:raise ValueError((rev,path,part))
  mode,oid=found;chain.append({'tree':cur,'name':part,'mode':mode,'oid':oid});cur=oid
 b=(D/cap).read_bytes();assert hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()==cur
 proofs.append({'revision':rev,'root_tree':roots[rev],'path':path,'capture':cap,'blob':cur,'sha256':sha(b),'tree_chain':chain})
save('GIT-TREE-PROOFS.json',{'anchors':roots,'qualification':'Raw tree SHA-1 chains prove inclusion relative to the recorded roots; without independently available Git commit objects they do not independently bind a commit ID to a root tree. Author metadata is deliberately omitted.','proofs':proofs})

history=load('HISTORY-REGISTRATION.json')
for r in history['records']:
 b=(D/'history-exact'/r['record']).read_bytes();assert sha(b)==r['sha256']
